const definition: WorkflowDefinition = {
  id: "default",
  name: "轻快完成",
  version: "1.0.0",
  initialState: "open",
  states: {
    open: { label: "未完成", category: "open" },
    done: { label: "已完成", category: "done" },
  },
  actions: [
    { id: "complete", label: "完成", from: ["open"] },
    { id: "reopen", label: "重新打开", from: ["done"] },
  ],
  fields: [
    { key: "review", label: "复盘", type: "text", required: true }
  ],
};

const plugin: Plugin = {
  describe() {
    return definition;
  },

  decide({ task, action, input }) {
    const validAction = definition.actions.find(
      (a) => a.id === action && a.from.includes(task.state)
    );

    if (!validAction) {
      return { kind: "reject", message: "当前状态不能执行此操作" };
    }

    if (action === "complete") {
      const rawReview = input.review;

      if (rawReview === undefined || rawReview === null || typeof rawReview !== "string" || rawReview.trim() === "") {
        return { 
          kind: "input-required", 
          fields: definition.fields 
        };
      }

      const review = rawReview.trim();
      const length = Array.from(review).length;

      if (length < 1 || length > 5000) {
        return { kind: "reject", message: "复盘内容长度需在 1 到 5000 个字之间" };
      }

      return {
        kind: "commit",
        state: "done",
        fields: {
          ...task.fields,
          review
        }
      };
    }

    if (action === "reopen") {
      return {
        kind: "commit",
        state: "open",
        fields: task.fields
      };
    }

    return { kind: "reject", message: "未知操作" };
  }
};

export default plugin;
