essage: \"未知操作\" };\n  }\n};\n\nexport default plugin;\n"},{"content":"export default {\n  title: \"任务详情\",\n  fields: [\"review\"]\n};\n","path":"business/view.ts"},{"content":"{}\n","path":"business/config.json"},{"content":"{\n  \"preserveUnknownFields\": true\n}\n","path":"business/compatibility.json"}]}","code":"const definition = {
